"""Regenerate the TPC-H-derived query files: ``python -m velocia.workloads.sql.generate``.

The text comes from DuckDB's ``tpch`` extension (``tpch_queries()``, the default substitution
parameters with dates already computed), which is valid Apache Spark SQL apart from the trailing
semicolon. Nothing from the TPC kits is vendored; a test checks the committed files are current.
"""

import sys
from pathlib import Path

import duckdb

from velocia.workloads.sql import QUERIES_DIR

HEADER = (
    "-- {unit_id}: derived from TPC-H Q{nr}; not an official TPC query or result.\n"
    "-- Generated by velocia.workloads.sql.generate from DuckDB tpch_queries(); do not edit.\n"
)


def tpch_queries() -> dict[str, str]:
    with duckdb.connect() as con:
        con.execute("SET autoinstall_known_extensions = false")
        con.execute("LOAD tpch")
        rows = con.execute("SELECT query_nr, query FROM tpch_queries() ORDER BY 1").fetchall()
    out = {}
    for nr, query in rows:
        body = "\n".join(line.rstrip() for line in query.strip().splitlines()).removesuffix(";")
        out[f"q{nr}.sql"] = HEADER.format(unit_id=f"q{nr}", nr=nr) + body + "\n"
    return out


def main(out_dir: Path = QUERIES_DIR / "tpch") -> None:
    out_dir.mkdir(parents=True, exist_ok=True)
    for name, text in tpch_queries().items():
        (out_dir / name).write_text(text, "utf-8")


if __name__ == "__main__":
    main(Path(sys.argv[1]) if len(sys.argv) > 1 else QUERIES_DIR / "tpch")
